fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len();
    
    while left < right {
        let mid = left + (right - left) / 2;
        
        if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    
    // Since we're guaranteed that k exists in the array,
    // left will be a valid index where v[left] == k
    left
}